<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
use Namira\{Db,Env,Installer,AdminPanel,Protocol,DomainMigration,HttpError,DataBackup};
$home=BASE_PATH.'/storage/domain-copy-test-'.bin2hex(random_bytes(7));$sourceRoot=$home.'/source';$live=$home.'/live';foreach([$sourceRoot.'/storage',$live.'/storage'] as $dir)mkdir($dir,0700,true);
$sourceDsn=getenv('TEST_DOMAIN_SOURCE_DSN')?:'sqlite:'.$sourceRoot.'/storage/source.sqlite';$targetDsn=getenv('TEST_DOMAIN_TARGET_DSN')?:'sqlite:'.$live.'/target.sqlite';foreach([$sourceDsn,$targetDsn] as $dsn)if(!str_starts_with($dsn,'sqlite:'.$home.'/')&&!preg_match('/dbname=namira_test_domain_(source|target)(?:;|$)/',$dsn))throw new RuntimeException('Isolated domain DB required');$dbUser=getenv('TEST_DB_USER')?:'';$dbPassword=getenv('TEST_DB_PASSWORD')?:'';
putenv('APP_ENV=testing');putenv('DB_DSN='.$sourceDsn);putenv('DB_USER='.$dbUser);putenv('DB_PASSWORD='.$dbPassword);putenv('STORAGE_PATH='.$sourceRoot.'/storage');putenv('PUBLIC_APP_URL=https://naamiraa.ir');putenv('ADMIN_APP_URL=https://admin.naamiraa.ir');$_SESSION=[];$source=Db::connect();(require BASE_PATH.'/database/migrate.php')($source);$uid=Db::insert($source,'users',['email'=>'migration-admin@example.test','password_hash'=>password_hash('test-migration-only',PASSWORD_DEFAULT),'role'=>'superadmin']);$admin=['id'=>$uid,'role'=>'superadmin','email'=>'migration-admin@example.test'];AdminPanel::boot($source,$admin);$person=(new Protocol($source,$admin))->quick(['code'=>'001024','first_name'=>'پرونده','last_name'=>'انتقال']);
file_put_contents($sourceRoot.'/storage/original.bin',random_bytes(2048));$oldConfig=['APP_URL'=>'https://test.shahidpics.com','DB_DSN'=>$sourceDsn,'DB_USER'=>$dbUser,'DB_PASSWORD'=>$dbPassword,'STORAGE_PATH'=>$sourceRoot.'/storage','OTP_SECRET'=>'test-only-long-unchanged-otp-secret'];file_put_contents($sourceRoot.'/config.local.json',json_encode($oldConfig));$counts=DataBackup::counts($source);$hash=hash_file('sha256',$sourceRoot.'/storage/original.bin');
putenv('STORAGE_PATH='.$live.'/storage');file_put_contents($live.'/.migration-source.json',json_encode(['root'=>$sourceRoot]));$key=bin2hex(random_bytes(32));file_put_contents($live.'/.setup.key',$key);$installer=new Installer($live);$installer->unlock($key);$target=new PDO($targetDsn,$dbUser,$dbPassword,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$config=['DB_DSN'=>$targetDsn,'DB_USER'=>$dbUser,'DB_PASSWORD'=>$dbPassword,'APP_URL'=>'https://naamiraa.ir'];$report=$installer->installCopy($target,$config);$n=0;
function check(bool $v,string $s):void {global $n;if(!$v)throw new RuntimeException($s);echo 'PASS '.$s.PHP_EOL;$n++;}
check(DataBackup::counts($target)===$counts,'all original table counts preserved in independent database');check(Db::query($target,'SELECT code FROM martyrs WHERE id=?',[$person])->fetchColumn()==='001024','archive zeroes and martyr identity preserved');check(hash_file('sha256',$live.'/storage/original.bin')===$hash,'original file copied byte-identically');check(DataBackup::counts($source)===$counts,'source database unchanged');$saved=json_decode(file_get_contents($live.'/config.local.json'),true);check($saved['DB_DSN']===$config['DB_DSN']&&$saved['PUBLIC_APP_URL']==='https://naamiraa.ir'&&$saved['ADMIN_APP_URL']==='https://admin.naamiraa.ir','only destination credentials and origins applied');check($saved['OTP_SECRET']===$oldConfig['OTP_SECRET'],'existing private application secrets retained');check(password_verify('test-migration-only',Db::query($target,'SELECT password_hash FROM users WHERE id=?',[$uid])->fetchColumn()),'existing administrator credentials retained');check(!$installer->enabled()&&!is_file($live.'/.setup.key'),'installer locked and setup key consumed');check($report['source_modified']===false&&is_file($live.'/domain-migration-report.json'),'private migration evidence recorded');
try{$installer->installCopy($target,$config);throw new RuntimeException('repeat accepted');}catch(HttpError $e){check($e->status===403,'repeated copy rejected');}
$nonempty=new PDO('sqlite:'.$home.'/nonempty.sqlite');$nonempty->exec('CREATE TABLE do_not_touch (id INTEGER)');$nonempty->exec('INSERT INTO do_not_touch VALUES (1)');try{DomainMigration::copy($live,$nonempty,$config);throw new RuntimeException('nonempty accepted');}catch(HttpError $e){check($e->status===422&&(int)$nonempty->query('SELECT COUNT(*) FROM do_not_touch')->fetchColumn()===1,'nonempty destination rejected without modification');}
echo $n.' domain migration checks passed'.PHP_EOL;
